import{L as e,b as t,x as n}from"./vue-Vea_iehr.js";import{oi as r}from"./common-BpDe505I.js";var i=JSON.parse(`{"path":"/os/debian/ds4tuka2/","title":"允许 Root 远程 SSH 登录 | Debian","lang":"zh-CN","frontmatter":{"title":"允许 Root 远程 SSH 登录","createTime":"2026/08/25 16:51:38","permalink":"/os/debian/ds4tuka2/"},"readingTime":{"minutes":1.51,"words":453},"git":{},"filePathRelative":"os/debian/001.allow-root-remote-ssh-login.md","headers":[]}`),a={name:`001.allow-root-remote-ssh-login.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h2 id="概述" tabindex="-1"><a class="header-anchor" href="#概述"><span>概述</span></a></h2><p>Debian 12 默认禁止 root 通过密码远程登录 SSH（默认 <code>PermitRootLogin prohibit-password</code>，仅允许密钥登录或无密码方式）。本文记录如何在 Debian 12 中开启 root 远程 SSH 登录（含密码认证），以及如何配置防火墙放行与事后恢复默认。该操作会降低系统安全性，仅建议在隔离内网或临时调试场景下使用。</p><h2 id="一、修改-ssh-服务端配置" tabindex="-1"><a class="header-anchor" href="#一、修改-ssh-服务端配置"><span>一、修改 SSH 服务端配置</span></a></h2><ol><li><p>备份原配置文件：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ssh/sshd_config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ssh/sshd_config.bak</span></span></code></pre></div></li><li><p>编辑 SSH 配置文件：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ssh/sshd_config</span></span></code></pre></div></li><li><p>找到并修改以下参数（行首 <code>#</code> 注释符需一并删除）：</p><div class="language-ini" data-highlighter="shiki" data-ext="ini" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-ini"><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PermitRootLogin yes</span></span></code></pre></div><div class="language-ini" data-highlighter="shiki" data-ext="ini" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-ini"><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PasswordAuthentication yes</span></span></code></pre></div></li><li><p>保存并退出（Nano：<kbd>Ctrl</kbd>+<kbd>O</kbd> 保存，<kbd>Ctrl</kbd>+<kbd>X</kbd> 退出）。</p></li></ol><h2 id="二、重启-ssh-服务" tabindex="-1"><a class="header-anchor" href="#二、重启-ssh-服务"><span>二、重启 SSH 服务</span></a></h2><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span></code></pre></div><h2 id="三、验证配置" tabindex="-1"><a class="header-anchor" href="#三、验证配置"><span>三、验证配置</span></a></h2><ol><li><p>检查服务状态，确认处于 <code>active (running)</code>：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span></code></pre></div></li><li><p>从另一台机器测试远程 root 登录：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root@your_server_ip</span></span></code></pre></div><p>输入 root 密码，确认能否成功登录。</p></li></ol><h2 id="四、配置防火墙放行-ssh" tabindex="-1"><a class="header-anchor" href="#四、配置防火墙放行-ssh"><span>四、配置防火墙放行 SSH</span></a></h2><p>若系统启用了防火墙（如 <code>ufw</code>），需放行 SSH 端口（默认 22）：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 22/tcp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span></span></code></pre></div><h2 id="五、恢复默认配置-禁止-root-登录" tabindex="-1"><a class="header-anchor" href="#五、恢复默认配置-禁止-root-登录"><span>五、恢复默认配置（禁止 Root 登录）</span></a></h2><ol><li><p>将 <code>PermitRootLogin</code> 改为 <code>prohibit-password</code>（仅允许密钥登录，禁止密码登录 root）：</p><div class="language-ini" data-highlighter="shiki" data-ext="ini" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-ini"><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PermitRootLogin prohibit-password</span></span></code></pre></div></li><li><p>重启 SSH 服务：</p><div class="language-bash" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;"><pre class="shiki shiki-themes github-light github-dark vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span></span></code></pre></div></li></ol><div class="hint-container warning"><p class="hint-container-title">警告</p><p>开放 root 密码远程登录会显著增加服务器被暴力破解的风险，建议仅在必要时临时开启，调试结束后及时按第五节恢复默认。</p></div><div class="hint-container tip"><p class="hint-container-title">提示</p><p>更安全的做法：使用普通用户登录后通过 <code>su -</code> 或 <code>sudo</code> 获取 root 权限；或保持 <code>PermitRootLogin prohibit-password</code> 并配置 SSH 密钥登录 root，避免密码暴露。</p></div>`,15)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};